{"path": "/workspace/coffee-landing.html", "content": "<!DOCTYPE html>
<html lang="zh-CN">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>岩韵 · ROCK RHYTHM — 单一产地手冲咖啡</title>
<style>
  /* ===== RESET & BASE ===== */
  *, *::before, *::after { margin: 0; padding: 0; box-sizing: border-box; }
  html { scroll-behavior: smooth; }
  body {
    font-family: 'Inter', 'PingFang SC', 'Microsoft YaHei', -apple-system, sans-serif;
    background: #1B1815;
    color: #D4CFC8;
    line-height: 1.6;
    -webkit-font-smoothing: antialiased;
    overflow-x: hidden;
  }

  /* ===== FONTS ===== */
  @import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600&family=Noto+Serif+SC:wght@400;600;700;900&family=Playfair+Display:ital,wght@0,400;0,700;0,900;1,400&display=swap');

  /* ===== PALETTE ===== */
  :root {
    --bed:        #1B1815;  /* 萃取床 — 深棕近黑 */
    --crema:      #F4F0EB;  /* 油脂层 — 暖白 */
    --first-drip: #CB6F47;  /* 初滴 — 琥珀铜 */
    --wet-filter: #947A62;  /* 湿滤纸 — 灰棕 */
    --soil:       #3E5C4A;  /* 产区土壤 — 深绿 */
    --bloom-foam: #E8DCC8;  /* 闷蒸泡沫 — 浅暖 */
    --surface:    #24201C;  /* 卡片表面 */
    --muted:      #8A8278;  /* 弱化文字 */
  }

  /* ===== TYPOGRAPHY ===== */
  .serif-display {
    font-family: 'Playfair Display', 'Noto Serif SC', Georgia, serif;
    font-weight: 900;
    letter-spacing: -0.02em;
  }
  .serif-sub {
    font-family: 'Playfair Display', 'Noto Serif SC', Georgia, serif;
    font-weight: 400;
    font-style: italic;
  }
  .label {
    font-family: 'Inter', 'PingFang SC', sans-serif;
    font-size: 0.675rem;
    font-weight: 600;
    letter-spacing: 0.18em;
    text-transform: uppercase;
    color: var(--muted);
  }

  /* ===== EXTRACTION PROGRESS TRACKER ===== */
  #extraction-indicator {
    position: fixed;
    top: 50%;
    right: 32px;
    transform: translateY(-50%);
    z-index: 100;
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 20px;
  }
  .extraction-dot {
    width: 6px; height: 6px;
    border-radius: 50%;
    background: #3D3630;
    transition: all 0.5s cubic-bezier(0.25, 0.46, 0.45, 0.94);
    position: relative;
  }
  .extraction-dot::after {
    content: attr(data-stage);
    position: absolute;
    right: 18px;
    top: 50%;
    transform: translateY(-50%);
    font-size: 0.625rem;
    letter-spacing: 0.12em;
    text-transform: uppercase;
    color: #5D5650;
    white-space: nowrap;
    opacity: 0;
    transition: opacity 0.4s;
    font-family: 'Inter', sans-serif;
    font-weight: 500;
  }
  .extraction-dot.active {
    background: var(--first-drip);
    box-shadow: 0 0 12px rgba(203,111,71,0.5);
    width: 8px; height: 8px;
  }
  .extraction-dot.active::after { opacity: 1; color: var(--first-drip); }
  .extraction-line {
    width: 1px;
    height: 24px;
    background: linear-gradient(to bottom, #3D3630, transparent);
  }

  /* ===== SECTIONS ===== */
  section {
    min-height: 100vh;
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 80px 40px;
    position: relative;
    transition: background 0.8s ease;
  }
  .container {
    max-width: 1100px;
    width: 100%;
    margin: 0 auto;
  }

  /* ===== HERO ===== */
  #hero {
    background: #1B1815;
    min-height: 100vh;
    display: flex;
    align-items: center;
    justify-content: center;
    text-align: center;
    position: relative;
    overflow: hidden;
  }

  /* Coffee bloom particle effect */
  .bloom-particles {
    position: absolute;
    inset: 0;
    pointer-events: none;
    opacity: 0.4;
  }
  .bloom-particle {
    position: absolute;
    border-radius: 50%;
    background: radial-gradient(circle, var(--first-drip) 0%, transparent 70%);
    animation: float-up 8s ease-in infinite;
    opacity: 0;
  }
  @keyframes float-up {
    0%   { transform: translateY(100vh) scale(0); opacity: 0; }
    10%  { opacity: 0.6; }
    50%  { opacity: 0.3; transform: translateY(40vh) scale(1); }
    100% { transform: translateY(-10vh) scale(0.3); opacity: 0; }
  }

  .hero-content {
    position: relative;
    z-index: 2;
  }
  .hero-eyebrow {
    font-family: 'Inter', sans-serif;
    font-size: 0.7rem;
    font-weight: 500;
    letter-spacing: 0.25em;
    text-transform: uppercase;
    color: var(--first-drip);
    margin-bottom: 24px;
  }
  .hero-title {
    font-family: 'Playfair Display', 'Noto Serif SC', serif;
    font-size: clamp(3.5rem, 8vw, 7rem);
    font-weight: 900;
    color: var(--crema);
    line-height: 1.05;
    letter-spacing: -0.03em;
    margin-bottom: 8px;
  }
  .hero-title .accent {
    color: var(--first-drip);
    font-style: italic;
  }
  .hero-sub {
    font-family: 'Inter', 'PingFang SC', sans-serif;
    font-size: 1rem;
    font-weight: 300;
    color: var(--wet-filter);
    max-width: 480px;
    margin: 0 auto 48px;
    letter-spacing: 0.04em;
  }
  .hero-drip-line {
    width: 1px;
    height: 64px;
    background: linear-gradient(to bottom, var(--first-drip), transparent);
    margin: 0 auto 32px;
    animation: drip-pulse 2.5s ease-in-out infinite;
  }
  @keyframes drip-pulse {
    0%, 100% { opacity: 0.3; transform: scaleY(1); }
    50%      { opacity: 1; transform: scaleY(1.15); }
  }

  /* Pour rings in hero */
  .pour-rings {
    position: absolute;
    top: 50%; left: 50%;
    transform: translate(-50%, -50%);
    pointer-events: none;
    opacity: 0.06;
  }
  .pour-ring {
    position: absolute;
    border-radius: 50%;
    border: 1px solid var(--crema);
    top: 50%; left: 50%;
    transform: translate(-50%, -50%);
    animation: pour-expand 6s ease-out infinite;
  }
  @keyframes pour-expand {
    0%   { width: 80px; height: 80px; opacity: 1; }
    100% { width: 600px; height: 600px; opacity: 0; }
  }

  /* ===== ORIGIN ===== */
  #origin {
    background: #201C18;
  }
  #origin .container {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 80px;
    align-items: center;
  }
  .origin-visual {
    position: relative;
  }
  .origin-map-glyph {
    width: 100%;
    aspect-ratio: 1;
    border-radius: 50%;
    background: radial-gradient(circle at 30% 40%, #3E3A34 0%, #1E1B17 100%);
    display: flex;
    align-items: center;
    justify-content: center;
    position: relative;
    overflow: hidden;
  }
  .origin-map-glyph::before {
    content: '';
    position: absolute;
    inset: 20%;
    border-radius: 50%;
    border: 1px solid rgba(203,111,71,0.3);
    animation: contour-pulse 4s ease-in-out infinite;
  }
  @keyframes contour-pulse {
    0%, 100% { transform: scale(1); opacity: 0.3; }
    50%      { transform: scale(1.05); opacity: 0.6; }
  }
  .origin-map-glyph .elevation {
    position: absolute;
    font-family: 'Playfair Display', serif;
    font-size: 0.6rem;
    color: var(--first-drip);
    letter-spacing: 0.2em;
    text-transform: uppercase;
    opacity: 0.6;
  }
  .origin-text .label { margin-bottom: 16px; }
  .origin-text h2 {
    font-family: 'Playfair Display', 'Noto Serif SC', serif;
    font-size: clamp(2rem, 4vw, 3rem);
    font-weight: 900;
    color: var(--crema);
    line-height: 1.15;
    margin-bottom: 24px;
    letter-spacing: -0.02em;
  }
  .origin-text h2 em { color: var(--first-drip); font-style: italic; }
  .origin-text p {
    color: var(--muted);
    font-size: 0.95rem;
    line-height: 1.8;
    margin-bottom: 40px;
  }

  /* Tasting notes wheel */
  .tasting-wheel {
    display: flex;
    gap: 12px;
    flex-wrap: wrap;
  }
  .taste-tag {
    padding: 8px 16px;
    border: 1px solid rgba(203,111,71,0.25);
    border-radius: 24px;
    font-size: 0.8rem;
    color: var(--bloom-foam);
    letter-spacing: 0.04em;
    transition: all 0.3s;
    cursor: default;
    background: rgba(203,111,71,0.04);
  }
  .taste-tag:hover {
    border-color: var(--first-drip);
    background: rgba(203,111,71,0.12);
    color: var(--first-drip);
  }

  /* ===== PROCESS ===== */
  #process {
    background: #1B1815;
    overflow: hidden;
  }
  #process .container {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 80px;
    align-items: center;
  }
  .process-steps {
    display: flex;
    flex-direction: column;
    gap: 40px;
  }
  .process-step {
    display: flex;
    gap: 20px;
    align-items: flex-start;
    position: relative;
  }
  .step-marker {
    width: 48px; height: 48px;
    border-radius: 50%;
    border: 1.5px solid rgba(203,111,71,0.4);
    display: flex;
    align-items: center;
    justify-content: center;
    flex-shrink: 0;
    font-family: 'Playfair Display', serif;
    font-size: 1.2rem;
    font-weight: 700;
    color: var(--first-drip);
    transition: all 0.4s;
  }
  .process-step:hover .step-marker {
    background: var(--first-drip);
    color: #1B1815;
    border-color: var(--first-drip);
  }
  .step-body h4 {
    font-family: 'Playfair Display', 'Noto Serif SC', serif;
    font-size: 1.25rem;
    font-weight: 700;
    color: var(--crema);
    margin-bottom: 6px;
  }
  .step-body p {
    font-size: 0.85rem;
    color: var(--muted);
    line-height: 1.7;
  }
  .step-temp {
    font-family: 'Inter', monospace;
    font-size: 0.7rem;
    color: var(--first-drip);
    letter-spacing: 0.1em;
    margin-top: 4px;
  }
  .process-visual {
    position: relative;
    display: flex;
    align-items: center;
    justify-content: center;
  }
  .dripper-illustration {
    width: 240px; height: 240px;
    position: relative;
  }
  .dripper-cone {
    position: absolute;
    bottom: 20px; left: 50%;
    transform: translateX(-50%);
    width: 120px; height: 140px;
    background: linear-gradient(175deg, #3D3630 0%, #25201A 100%);
    clip-path: polygon(15% 0%, 85% 0%, 100% 100%, 0% 100%);
    border-radius: 4px 4px 0 0;
  }
  .dripper-ring {
    position: absolute;
    bottom: 150px; left: 50%;
    transform: translateX(-50%);
    width: 140px; height: 20px;
    border: 2px solid #5D5650;
    border-radius: 50%;
    border-bottom: none;
  }
  .steam-line {
    position: absolute;
    width: 2px;
    height: 60px;
    background: linear-gradient(to top, rgba(203,111,71,0.4), transparent);
    animation: steam-rise 2s ease-out infinite;
  }
  @keyframes steam-rise {
    0%   { transform: translateY(0) scaleX(1); opacity: 0.6; }
    100% { transform: translateY(-60px) scaleX(2); opacity: 0; }
  }

  /* ===== PRODUCT ===== */
  #product {
    background: #201C18;
  }
  #product .container {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 80px;
    align-items: center;
  }
  .product-card {
    background: var(--surface);
    border: 1px solid rgba(148,122,98,0.15);
    border-radius: 2px;
    padding: 48px;
    position: relative;
    transition: border-color 0.4s;
  }
  .product-card:hover {
    border-color: rgba(203,111,71,0.4);
  }
  .product-card .label { margin-bottom: 12px; }
  .product-card h3 {
    font-family: 'Playfair Display', 'Noto Serif SC', serif;
    font-size: 2rem;
    font-weight: 900;
    color: var(--crema);
    margin-bottom: 8px;
  }
  .product-card .variety {
    font-family: 'Inter', sans-serif;
    font-size: 0.8rem;
    color: var(--wet-filter);
    letter-spacing: 0.08em;
    margin-bottom: 24px;
  }
  .spec-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 16px;
    margin-bottom: 32px;
  }
  .spec-item .spec-label {
    font-size: 0.625rem;
    letter-spacing: 0.15em;
    text-transform: uppercase;
    color: var(--muted);
    margin-bottom: 4px;
  }
  .spec-item .spec-value {
    font-family: 'Inter', sans-serif;
    font-size: 0.9rem;
    font-weight: 500;
    color: var(--crema);
  }
  .btn-primary {
    display: inline-block;
    padding: 14px 36px;
    background: var(--first-drip);
    color: #1B1815;
    font-family: 'Inter', sans-serif;
    font-size: 0.85rem;
    font-weight: 600;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    border: none;
    cursor: pointer;
    border-radius: 1px;
    transition: all 0.3s;
    text-decoration: none;
  }
  .btn-primary:hover {
    background: #D47E5C;
    transform: translateY(-1px);
    box-shadow: 0 8px 24px rgba(203,111,71,0.25);
  }
  .product-visual {
    position: relative;
  }
  .bean-abstract {
    width: 100%;
    aspect-ratio: 3/4;
    background: linear-gradient(160deg, #2A2520 0%, #1B1815 60%, #3D3630 100%);
    border-radius: 1px;
    overflow: hidden;
    position: relative;
  }
  .bean-abstract::after {
    content: '';
    position: absolute;
    inset: 0;
    background:
      radial-gradient(ellipse at 30% 20%, rgba(203,111,71,0.15) 0%, transparent 60%),
      radial-gradient(ellipse at 70% 80%, rgba(62,92,74,0.12) 0%, transparent 60%);
  }
  .steam-wisp {
    position: absolute;
    width: 80px; height: 2px;
    background: linear-gradient(90deg, transparent, rgba(212,207,200,0.15), transparent);
    border-radius: 1px;
    animation: wisp-drift 5s ease-in-out infinite;
  }
  @keyframes wisp-drift {
    0%, 100% { transform: translateY(0) translateX(0); opacity: 0; }
    20%      { opacity: 0.5; }
    50%      { transform: translateY(-30px) translateX(10px); opacity: 0.3; }
    80%      { opacity: 0.1; }
  }

  /* ===== FOOTER ===== */
  footer {
    background: #181510;
    padding: 64px 40px 32px;
    text-align: center;
    border-top: 1px solid rgba(148,122,98,0.1);
  }
  .footer-brand {
    font-family: 'Playfair Display', 'Noto Serif SC', serif;
    font-size: 1.5rem;
    font-weight: 900;
    color: var(--crema);
    margin-bottom: 8px;
  }
  .footer-tagline {
    font-size: 0.75rem;
    color: var(--muted);
    letter-spacing: 0.1em;
    margin-bottom: 32px;
  }
  .footer-line {
    width: 40px; height: 1px;
    background: var(--first-drip);
    margin: 0 auto 32px;
    opacity: 0.5;
  }
  .footer-links {
    display: flex;
    gap: 32px;
    justify-content: center;
    flex-wrap: wrap;
    font-size: 0.75rem;
    letter-spacing: 0.08em;
  }
  .footer-links a {
    color: var(--muted);
    text-decoration: none;
    transition: color 0.3s;
  }
  .footer-links a:hover { color: var(--first-drip); }
  .footer-credit {
    margin-top: 40px;
    font-size: 0.65rem;
    color: #4D4740;
    letter-spacing: 0.1em;
  }

  /* ===== RESPONSIVE ===== */
  @media (max-width: 768px) {
    section { padding: 60px 24px; min-height: auto; }
    #origin .container,
    #process .container,
    #product .container {
      grid-template-columns: 1fr;
      gap: 48px;
    }
    #origin .container { grid-template-columns: 1fr; }
    .origin-visual { order: -1; }
    #extraction-indicator { display: none; }
    .hero-title { font-size: clamp(2.5rem, 10vw, 4rem); }
    .product-card { padding: 32px; }
  }

  /* Reduced motion */
  @media (prefers-reduced-motion: reduce) {
    .bloom-particle, .pour-ring, .steam-wisp,
    .hero-drip-line, .dripper-ring {
      animation: none !important;
    }
  }

  /* Focus visible */
  .btn-primary:focus-visible,
  a:focus-visible {
    outline: 2px solid var(--first-drip);
    outline-offset: 4px;
  }
</style>
</head>
<body>

<!-- Extraction Progress Indicator -->
<nav id="extraction-indicator" aria-label="页面导航">
  <div class="extraction-dot active" data-stage="研磨" data-section="hero"></div>
  <div class="extraction-line"></div>
  <div class="extraction-dot" data-stage="产地" data-section="origin"></div>
  <div class="extraction-line"></div>
  <div class="extraction-dot" data-stage="冲煮" data-section="process"></div>
  <div class="extraction-line"></div>
  <div class="extraction-dot" data-stage="出品" data-section="product"></div>
</nav>

<!-- ===== HERO ===== -->
<section id="hero">
  <div class="bloom-particles" aria-hidden="true">
    <div class="bloom-particle" style="left:15%; animation-delay:0s; width:4px; height:4px;"></div>
    <div class="bloom-particle" style="left:30%; animation-delay:2s; width:6px; height:6px;"></div>
    <div class="bloom-particle" style="left:50%; animation-delay:4s; width:3px; height:3px;"></div>
    <div class="bloom-particle" style="left:65%; animation-delay:1s; width:5px; height:5px;"></div>
    <div class="bloom-particle" style="left:80%; animation-delay:3s; width:4px; height:4px;"></div>
    <div class="bloom-particle" style="left:45%; animation-delay:5s; width:7px; height:7px;"></div>
    <div class="bloom-particle" style="left:22%; animation-delay:2.5s; width:3px; height:3px;"></div>
  </div>

  <div class="pour-rings" aria-hidden="true">
    <div class="pour-ring" style="animation-delay:0s;"></div>
    <div class="pour-ring" style="animation-delay:2s;"></div>
    <div class="pour-ring" style="animation-delay:4s;"></div>
  </div>

  <div class="hero-content">
    <p class="hero-eyebrow">单一产地 · 手冲专研</p>
    <h1 class="hero-title">
      岩<br>韵<span class="accent">·</span>
    </h1>
    <p class="hero-sub">
      每一颗豆子都是地质运动的遗言。<br>
      我们用三分钟，把它翻译成你杯中的语言。
    </p>
    <div class="hero-drip-line" aria-hidden="true"></div>
  </div>
</section>

<!-- ===== ORIGIN ===== -->
<section id="origin">
  <div class="container">
    <div class="origin-visual">
      <div class="origin-map-glyph">
        <span class="elevation" style="top:18%; left:42%;">1,800m</span>
        <span class="elevation" style="top:38%; left:55%;">1,650m</span>
        <span class="elevation" style="top:52%; left:35%;">2,100m</span>
        <span class="elevation" style="top:62%; left:50%;">1,950m</span>
        <span class="elevation" style="top:28%; left:60%;">2,300m</span>
      </div>
    </div>
    <div class="origin-text">
      <p class="label">产区溯源</p>
      <h2>耶加雪菲<br><em>果丁丁合作社</em></h2>
      <p>
        埃塞俄比亚南部，海拔 1,800–2,300 米的火山土壤带。
        红铁铝土与玄武岩母质赋予咖啡豆独特的矿物骨架——
        明亮而不刺，复杂而不乱。果丁丁合作社的 847 户小农
        只采收全红果，日晒 21 天，每一批都有独立的微批次编号。
      </p>
      <div class="tasting-wheel">
        <span class="taste-tag">佛手柑</span>
        <span class="taste-tag">蜜桃</span>
        <span class="taste-tag">伯爵茶</span>
        <span class="taste-tag">蜂蜜</span>
        <span class="taste-tag">柠檬皮</span>
        <span class="taste-tag">花香</span>
      </div>
    </div>
  </div>
</section>

<!-- ===== PROCESS ===== -->
<section id="process">
  <div class="container">
    <div class="process-steps">
      <div class="process-step">
        <div class="step-marker">01</div>
        <div class="step-body">
          <h4>研磨</h4>
          <p>EK43 磨豆机，粒径分布集中在 700–900μm，
          确保均匀萃取。中细研磨，触感如海盐。</p>
          <span class="step-temp">粒径 · 800μm</span>
        </div>
      </div>
      <div class="process-step">
        <div class="step-marker">02</div>
        <div class="step-body">
          <h4>闷蒸</h4>
          <p>30 秒，两倍水量。让二氧化碳逃逸，
          为后续萃取打开通道。此刻的膨起——叫「Bloom」。</p>
          <span class="step-temp">水量比 · 1:2</span>
        </div>
      </div>
      <div class="process-step">
        <div class="step-marker">03</div>
        <div class="step-body">
          <h4>注水</h4>
