<script>
  // ===== Extraction stage scroll tracking =====
  const dots = document.querySelectorAll('.extraction-dot');
  const sections = ['hero', 'origin', 'process', 'product'];

  // Map each dot to its section
  const dotToSection = {};
  dots.forEach(dot => {
    const sec = dot.getAttribute('data-section');
    dotToSection[sec] = dot;
  });

  function updateExtractionIndicator() {
    const scrollPos = window.scrollY + window.innerHeight * 0.4;

    // Determine current section
    let currentSection = sections[0];
    for (const sec of sections) {
      const el = document.getElementById(sec);
      if (!el) continue;
      const rect = el.getBoundingClientRect();
      const elTop = rect.top + window.scrollY;
      if (scrollPos >= elTop) {
        currentSection = sec;
      }
    }

    // Update dots
    dots.forEach(dot => dot.classList.remove('active'));
    const currentDot = dotToSection[currentSection];
    if (currentDot) currentDot.classList.add('active');

    // Shift body background subtly based on scroll depth
    const progress = sections.indexOf(currentSection) / (sections.length - 1);
    const hueShift = Math.round(progress * 3); // subtle warm shift
    document.body.style.background = `hsl(30, ${6 + progress * 2}%, ${9.5 + progress * 1}%)`;
  }

  // Throttled scroll listener
  let ticking = false;
  window.addEventListener('scroll', () => {
    if (!ticking) {
      requestAnimationFrame(() => {
        updateExtractionIndicator();
        ticking = false;
      });
      ticking = true;
    }
  }, { passive: true });

  // Initial call
  updateExtractionIndicator();
</script>

